#!/usr/bin/env python3

import antlr4 as a4

# automatically trigger ANTLR4 Java tool, if we fail to import the files
# generated by it
try:
    from gelb.antlr_part.generated_code.GeLBLexer import GeLBLexer
    from gelb.antlr_part.generated_code.GeLBParser import GeLBParser
    from gelb.antlr_part.generated_code.GeLBVisitor import GeLBVisitor
except ModuleNotFoundError:
    from gelb.utils.misc import invoke_antlr4_tool
    invoke_antlr4_tool()
    from gelb.antlr_part.generated_code.GeLBLexer import GeLBLexer
    from gelb.antlr_part.generated_code.GeLBParser import GeLBParser
    from gelb.antlr_part.generated_code.GeLBVisitor import GeLBVisitor

from gelb.frontend.ASTBuilderVisitor import ASTBuilderVisitor
from gelb.frontend.ASTInitialValidationVisitor import ASTInitialValidationVisitor
from gelb.frontend.SymbolsTablesBuilderVisitor import SymbolsTablesBuilderVisitor
from gelb.frontend.ImplicitsRefsClashPreventerVisitor import ImplicitsRefsClashPreventerVisitor
from gelb.frontend.ImplicitsDefsClashPreventerVisitor import ImplicitsDefsClashPreventerVisitor
from gelb.frontend.ImplicitSymbolsAdderVisitor import ImplicitSymbolsAdderVisitor
from gelb.frontend.NodeClassesValidationVisitor import NodeClassesValidationVisitor
from gelb.frontend.GeometryInitialValidationVisitor import GeometryInitialValidationVisitor
from gelb.frontend.ConstantsResolverVisitor import ConstantsResolverVisitor
from gelb.frontend.RectangularArraysEnforcerVisitor import RectangularArraysEnforcerVisitor
from gelb.frontend.RangeResolverVisitor import RangeResolverVisitor
from gelb.frontend.ParsingError import ParsingError
from gelb.utils.exceptions import *
from gelb.utils.misc import ensure_file_is_not_empty_or_whitespace
import gelb.utils.config


def get_cst_as_string(start_rule, input_string):
    input_stream = a4.InputStream(input_string)
    lexer = GeLBLexer(input_stream)
    token_stream = a4.CommonTokenStream(lexer)
    token_stream.fill()
    parser = GeLBParser(token_stream)
    parser.removeErrorListeners()
    parser.addErrorListener(ParsingError())

    if hasattr(parser, start_rule):
        func_start_rule = getattr(parser, start_rule)
        cst = func_start_rule()
        return cst.toStringTree(recog=parser)
    else:
        raise GeLBExInvalidGrammarRule(start_rule)


def get_ast(start_rule, input_string):
    ensure_file_is_not_empty_or_whitespace(input_string)
    
    input_stream = a4.InputStream(input_string)
    lexer = GeLBLexer(input_stream)
    token_stream = a4.CommonTokenStream(lexer)
    token_stream.fill()
    
    parser = GeLBParser(token_stream)
    parser.removeErrorListeners()
    parser.addErrorListener(ParsingError())

    if hasattr(parser, start_rule):
        func_start_rule = getattr(parser, start_rule)

        cst = func_start_rule()

        ast_builder = ASTBuilderVisitor()
        visitation_method_name = f"visit{start_rule.capitalize()}"
        if hasattr(ast_builder, visitation_method_name):
            # trigger creation of (sub-)AST & return
            visitation_method = getattr(ast_builder, visitation_method_name)
            ast = visitation_method(cst)
            return ast
        else:
            raise GeLBExMissingCSTVisitationMethod(start_rule)
    else:
        raise GeLBExInvalidGrammarRule(start_rule)


def build_symbols_tables(ast, symbol_to_ignore_for_testing=None):
    ast_visitor = SymbolsTablesBuilderVisitor(symbol_to_ignore_for_testing)
    return ast_visitor.visit(ast, ast)


def prevent_clashes_of_symbol_refs_with_implicits(ast):
    ast_visitor = ImplicitsRefsClashPreventerVisitor()
    ast_visitor.visit(ast, ast)  # nothing to return here


def prevent_clashes_of_symbol_defs_with_implicits(ast):
    ast_visitor = ImplicitsDefsClashPreventerVisitor()
    ast_visitor.visit(ast, ast)  # nothing to return here


def add_implicit_symbols(ast):
    ast_visitor = ImplicitSymbolsAdderVisitor()
    return ast_visitor.visit(ast, ast)


def validate_node_classes(ast):
    ast_visitor = NodeClassesValidationVisitor()
    ast_visitor.visit(ast, ast)  # nothing to return here


def initial_validation_geometry(ast):
    ast_visitor = GeometryInitialValidationVisitor()
    ast_visitor.visit(ast, ast)  # nothing to return here


def resolve_all_constants(ast):
    ast_visitor = ConstantsResolverVisitor()
    return ast_visitor.visit(ast, ast)


def resolve_ranges(ast):
    """
    Replace None bounds in Range_N nodes with concrete values:
    - None lower bound → 0
    - None upper bound → Nx-1, Ny-1, or Nz-1 (based on dimension)
    
    Must run after symbol tables are built.
    """
    ast_visitor = RangeResolverVisitor()
    ast_visitor.visit(ast, ast)
    return ast


def enforce_rectangular_array_literals(ast):
    ast_visitor = RectangularArraysEnforcerVisitor()
    ast_visitor.visit(ast, ast)  # nothing to return here


def validate_ast(ast):
    ast_visitor = ASTInitialValidationVisitor()
    ast_visitor.visit(ast, ast)